<?php require_once __DIR__ . '/../bootstrap.php'; $input=body(); $name=clean($input['full_name']??''); $username=clean($input['username']??''); $email=filter_var($input['email']??'', FILTER_VALIDATE_EMAIL); $password=$input['password']??''; if (!$name||!preg_match('/^[a-zA-Z0-9_]{3,50}$/',$username)||!$email||strlen($password)<8||$password!==($input['confirm_password']??'')) respond(false,'Please provide valid registration details.',[],422); $check=$pdo->prepare('SELECT id FROM users WHERE email=? OR username=?'); $check->execute([$email,$username]); if($check->fetch()) respond(false,'That email or username is already in use.',[],409); $defaultImage='/api/uploads/profiles/SonoDefaultbald.jpg'; $stmt=$pdo->prepare('INSERT INTO users(full_name,username,email,password,profile_image) VALUES(?,?,?,?,?)'); $stmt->execute([$name,$username,$email,password_hash($password,PASSWORD_DEFAULT),$defaultImage]); $id=$pdo->lastInsertId(); $_SESSION['user']=['id'=>$id,'full_name'=>$name,'username'=>$username,'email'=>$email,'profile_image'=>$defaultImage,'role'=>'user']; respond(true,'Account created successfully.',['user'=>$_SESSION['user']],201);
